class Solution {
public:
    string reformatDate(string date) {
        vector<string> months = {"Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"};
        size_t i = 0; int day = 0;
        while (isdigit(date[i])) { day = day * 10 + (date[i] - '0'); i++; }
        i += 3;
        string m = date.substr(i, 3);
        int mon = find(months.begin(), months.end(), m) - months.begin() + 1;
        string year = date.substr(i + 4);
        char buf[11];
        snprintf(buf, sizeof(buf), "%s-%02d-%02d", year.c_str(), mon, day);
        return string(buf);
    }
};

